    deepExplanation: "Step 1 — Tree type:\n```ts\ninterface TreeNode {\n  value: number;\n  left: TreeNode | null;\n  right: TreeNode | null;\n}\n```\n\nStep 2 — WITHOUT BUILT-IN / CORE recursive traversals:\n```ts\ninterface TreeNode {\n  value: number;\n  left: TreeNode | null;\n  right: TreeNode | null;\n}\n\nfunction preorder(root: TreeNode | null): number[] {\n  if (root === null) return [];\n\n  return [\n    root.value,\n    ...preorder(root.left),\n    ...preorder(root.right),\n  ];\n}\n\nfunction inorder(root: TreeNode | null): number[] {\n  if (root === null) return [];\n\n  return [\n    ...inorder(root.left),\n    root.value,\n    ...inorder(root.right),\n  ];\n}\n\nfunction postorder(root: TreeNode | null): number[] {\n  if (root === null) return [];\n\n  return [\n    ...postorder(root.left),\n    ...postorder(root.right),\n    root.value,\n  ];\n}\n```\n\nStep 3 — WITH BUILT-IN-friendly iterative preorder:\n```ts\ninterface TreeNode {\n  value: number;\n  left: TreeNode | null;\n  right: TreeNode | null;\n}\n\nfunction preorderIterative(root: TreeNode | null): number[] {\n  if (root === null) return [];\n\n  const stack: TreeNode[] = [root];\n  const result: number[] = [];\n\n  while (stack.length > 0) {\n    const node = stack.pop()!;\n    result.push(node.value);\n\n    if (node.right !== null) stack.push(node.right);\n    if (node.left !== null) stack.push(node.left);\n  }\n\n  return result;\n}\n```\n\nStep 4 — Example:\n```text\n      1\n     /     2   3\n   /   4   5\n```\nPreorder = [1,2,4,5,3]\nInorder = [4,2,5,1,3]\nPostorder = [4,5,2,3,1]\n\nRecursive DFS uses O(h) stack; each traversal visits every node once.",
