    deepExplanation: "Step 1 — Initialize a queue with the root.\n\nWITHOUT BUILT-IN / CORE:\n```ts\ninterface TreeNode {\n  value: number;\n  left: TreeNode | null;\n  right: TreeNode | null;\n}\n\nfunction levelOrder(root: TreeNode | null): number[][] {\n  if (root === null) return [];\n\n  const queue: TreeNode[] = [root];\n  const result: number[][] = [];\n  let front = 0;\n\n  while (front < queue.length) {\n    const levelSize = queue.length - front;\n    const level: number[] = [];\n\n    for (let i = 0; i < levelSize; i++) {\n      const node = queue[front++]!;\n      level.push(node.value);\n\n      if (node.left !== null) queue.push(node.left);\n      if (node.right !== null) queue.push(node.right);\n    }\n\n    result.push(level);\n  }\n\n  return result;\n}\n```\n\nStep 2 — WITH BUILT-IN-friendly alternative:\n```ts\ninterface TreeNode {\n  value: number;\n  left: TreeNode | null;\n  right: TreeNode | null;\n}\n\nfunction levelOrderUsingMap(root: TreeNode | null): number[][] {\n  if (root === null) return [];\n\n  const levels: number[][] = [];\n  const queue: TreeNode[] = [root];\n  let front = 0;\n\n  while (front < queue.length) {\n    const size = queue.length - front;\n    const levelNodes = queue.slice(front, front + size);\n\n    levels.push(levelNodes.map((node) => node.value));\n    front += size;\n\n    for (const node of levelNodes) {\n      if (node.left !== null) queue.push(node.left);\n      if (node.right !== null) queue.push(node.right);\n    }\n  }\n\n  return levels;\n}\n```\n\nStep 3 — Example:\n```text\n      1\n     /     2   3\n   /   4   5\n```\nOutput:\n[[1],[2,3],[4,5]]\n\nStep 4 — Complexity:\nO(n) time; O(w) queue space, where w is maximum tree width.",
