    deepExplanation: "Step 1 — Use preorder with a null marker.\n\nWITHOUT BUILT-IN / CORE:\n```ts\ninterface TreeNode {\n  value: number;\n  left: TreeNode | null;\n  right: TreeNode | null;\n}\n\nfunction serialize(root: TreeNode | null): string {\n  const values: string[] = [];\n\n  function dfs(node: TreeNode | null): void {\n    if (node === null) {\n      values.push(\"#\");\n      return;\n    }\n\n    values.push(String(node.value));\n    dfs(node.left);\n    dfs(node.right);\n  }\n\n  dfs(root);\n  return values.join(\",\");\n}\n\nfunction deserialize(data: string): TreeNode | null {\n  const tokens = data.split(\",\");\n  let index = 0;\n\n  function build(): TreeNode | null {\n    const token = tokens[index++]!;\n\n    if (token === \"#\") return null;\n\n    return {\n      value: Number(token),\n      left: build(),\n      right: build(),\n    };\n  }\n\n  return build();\n}\n```\n\nWITH BUILT-IN-friendly:\n```ts\ninterface TreeNode {\n  value: number;\n  left: TreeNode | null;\n  right: TreeNode | null;\n}\n\nfunction serializeUsingJSON(root: TreeNode | null): string {\n  return JSON.stringify(root);\n}\n\nfunction deserializeUsingJSON(data: string): TreeNode | null {\n  return JSON.parse(data) as TreeNode | null;\n}\n```\n\nStep 2 — Example:\nTree:\n```text\n  1\n / 2   3\n```\nSerialized preorder:\n`1,2,#,#,3,#,#`\n\nStep 3 — Complexity:\nSerialization O(n).\nDeserialization O(n).\nThe serialized output is O(n).\n\nStep 4 — Important:\nA serialization without null markers can be ambiguous because different tree shapes can produce the same value order.",
