    deepExplanation: "Step 1 — Concept:\nEach edge represents a character; a path represents a prefix.\n\nWITHOUT BUILT-IN / CORE:\n```ts\nclass TrieNode {\n  children: Array<TrieNode | null> = new Array<TrieNode | null>(26).fill(null);\n  isWord = false;\n}\n\nclass Trie {\n  private readonly root = new TrieNode();\n\n  insert(word: string): void {\n    let node = this.root;\n\n    for (let i = 0; i < word.length; i++) {\n      const index = word.charCodeAt(i) - 97;\n\n      if (node.children[index] === null) {\n        node.children[index] = new TrieNode();\n      }\n\n      node = node.children[index]!;\n    }\n\n    node.isWord = true;\n  }\n\n  startsWith(prefix: string): boolean {\n    let node = this.root;\n\n    for (let i = 0; i < prefix.length; i++) {\n      const index = prefix.charCodeAt(i) - 97;\n      const next = node.children[index];\n\n      if (next === null) return false;\n      node = next;\n    }\n\n    return true;\n  }\n}\n```\n\nWITH BUILT-IN:\n```ts\nclass TrieWithMap {\n  private readonly root = new Map<string, Map<string, unknown>>();\n\n  insert(word: string): void {\n    let node = this.root;\n\n    for (const char of word) {\n      let next = node.get(char) as Map<string, Map<string, unknown>> | undefined;\n\n      if (!next) {\n        next = new Map<string, Map<string, unknown>>();\n        node.set(char, next);\n      }\n\n      node = next;\n    }\n\n    node.set(\"$\", new Map());\n  }\n\n  startsWith(prefix: string): boolean {\n    let node = this.root;\n\n    for (const char of prefix) {\n      const next = node.get(char) as Map<string, Map<string, unknown>> | undefined;\n      if (!next) return false;\n      node = next;\n    }\n\n    return true;\n  }\n}\n```\n\nStep 2 — Example:\nInsert `cat` and `car`.\nThe shared path is `c → a`, then branches to `t` and `r`.\n`startsWith(\"ca\")` → true.\n\nStep 3 — Complexity:\nInsert/search/prefix = O(L), where L is word/prefix length.\nSpace depends on total stored characters and sharing.",
